return [
  { json: { source: 'Demo ATS', source_id: 'DEMO-001', title: 'Workflow Automation Specialist', company: 'Northstar Services', location: 'Remote', description: 'Build n8n workflows, connect business tools, and improve implementation processes.', listed_on: '2026-08-20' } },
  { json: { source: 'Demo ATS', source_id: 'DEMO-002', title: 'AI Implementation Consultant', company: 'Cedar Labs', location: 'Hybrid', description: 'Lead client onboarding, systems integration, and repeatable delivery workflows.', listed_on: '2026-08-19' } },
  { json: { source: 'Demo ATS', source_id: 'DEMO-003', title: 'Software Engineer', company: 'Harbor Systems', location: 'Remote', description: 'Develop backend services and maintain application infrastructure.', listed_on: '2026-08-18' } },
  { json: { source: 'Demo ATS', source_id: 'DEMO-004', title: 'n8n Automation Builder', company: 'Brightway Studio', location: 'Remote', description: 'Create automation workflows and support process improvement projects.', listed_on: '2026-08-17' } },
  { json: { source: 'Demo ATS', source_id: 'DEMO-005', title: 'Sales Operations Analyst', company: 'Summit Works', location: 'On-site', description: 'Prepare reports, maintain forecasts, and coordinate sales planning.', listed_on: '2026-08-16' } }
];

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

return $input.all().map((item) => {
  const source = clean(item.json.source);
  const sourceId = clean(item.json.source_id);
  const title = clean(item.json.title);
  return {
    json: {
      record_key: `${source.toLowerCase().replace(/[^a-z0-9]+/g, '-')}:${sourceId}`,
      source,
      source_id: sourceId,
      title,
      normalized_title: title.toLowerCase(),
      company: clean(item.json.company),
      location: clean(item.json.location),
      description: clean(item.json.description),
      listed_on: clean(item.json.listed_on)
    }
  };
});

const titleTerms = ['automation', 'implementation', 'workflow', 'n8n'];
const supportingTerms = ['integration', 'client onboarding', 'process improvement'];
const threshold = 2;

return $input.all().map((item) => {
  const title = item.json.normalized_title;
  const details = `${title} ${item.json.description.toLowerCase()}`;
  const titleHits = titleTerms.filter((term) => title.includes(term));
  const supportingHits = supportingTerms.filter((term) => details.includes(term));
  const score = (titleHits.length * 2) + supportingHits.length;
  const reasons = [
    ...titleHits.map((term) => `title contains ${term}`),
    ...supportingHits.map((term) => `details contain ${term}`)
  ];
  return {
    json: {
      ...item.json,
      match_status: score >= threshold ? 'matched' : 'not_matched',
      match_score: score,
      match_reasons: reasons
    }
  };
});

const fictionalExistingKeys = new Set(['demo-ats:DEMO-004']);

return $input.all()
  .filter((item) => item.json.match_status === 'matched')
  .map((item) => ({
    json: {
      ...item.json,
      record_status: fictionalExistingKeys.has(item.json.record_key) ? 'existing' : 'new'
    }
  }));

return $input.all()
  .filter((item) => item.json.record_status === 'new')
  .map((item, index) => ({
    json: {
      ...item.json,
      preview_record_id: `PREVIEW-${String(index + 1).padStart(3, '0')}`,
      proposed_action: 'would_save_and_verify',
      database_write_performed: false
    }
  }));

const discovered = $items('Standardize Listings');
const evaluated = $items('Apply Fixed Matching Rules');
const matched = $items('Classify Existing Records');
const newRoles = $input.all();
const duplicates = matched.filter((item) => item.json.record_status === 'existing');

const roleLines = newRoles.map((item) => `• ${item.json.title} — ${item.json.company}`);
const message = [
  'Job Monitor offline preview',
  `${newRoles.length} new fictional match(es) would be saved and verified.`,
  ...roleLines,
  'No database write or Slack message was performed.'
].join('\n');

return [{
  json: {
    run_mode: 'offline_preview',
    discovered_count: discovered.length,
    matched_count: evaluated.filter((item) => item.json.match_status === 'matched').length,
    duplicate_count: duplicates.length,
    new_match_count: newRoles.length,
    database_write_performed: false,
    slack_message_sent: false,
    new_roles: newRoles.map((item) => ({ title: item.json.title, company: item.json.company })),
    slack_message_preview: message
  }
}];
